  this.ade = "\u042d\u0442\u043e \u043e\u043d(\u0430): \u043f\u043e\u0434\u0442\u0432\u0435\u0440\u0434\u0438\u0442\u044c";
  this.afP = "\u041e\u0431\u044a\u044f\u0432\u043b\u0435\u043d\u043e";
  this.ado = "\u041d\u0435 \u043e\u043d(\u0430): \u043e\u0442\u043a\u043b\u043e\u043d\u0438\u0442\u044c";
  this.acL = "\u0414\u043e\u0441\u043a\u0430";
  this.acP = "\u0427\u0442\u043e \u0443\u0447\u0430\u0441\u0442\u043d\u0438\u043a\u0438 \u043f\u0440\u0435\u0434\u043b\u0430\u0433\u0430\u044e\u0442 \u0438 \u0447\u0442\u043e \u0438\u0449\u0443\u0442. \u0426\u0435\u043d\u0430 \u2014 \u0432 \u043d\u0430\u0446\u0438\u043e\u043d\u0430\u043b\u044c\u043d\u043e\u0439 \u0432\u0430\u043b\u044e\u0442\u0435; \u0434\u043e\u043b\u044f \u0433\u043e\u0432\u043e\u0440\u0438\u0442, \u043a\u0430\u043a\u0430\u044f \u0435\u0451 \u0447\u0430\u0441\u0442\u044c \u0431\u0435\u0440\u0451\u0442\u0441\u044f \u0435\u0434\u0438\u043d\u0438\u0446\u0430\u043c\u0438, \u2014 \u043e\u0441\u0442\u0430\u043b\u044c\u043d\u043e\u0435 \u043f\u043b\u0430\u0442\u0438\u0442\u0441\u044f \u0434\u0435\u043d\u044c\u0433\u0430\u043c\u0438, \u0432\u043d\u0435 \u0441\u0438\u0441\u0442\u0435\u043c\u044b.";
  this.acO = "\u0412\u0438\u0434";
