  this.agO = "\u0438\u0449\u0435\u0442";
  this.acM = "\u043f\u043e\u043a\u0430 \u043f\u0443\u0441\u0442\u043e: \u0431\u0443\u0434\u044c\u0442\u0435 \u043f\u0435\u0440\u0432\u044b\u043c";
  this.afb = "\u041e\u0442\u043a\u0440\u044b\u0442\u044c";
  this.acq = "\u041f\u0440\u0435\u0434\u043b\u0430\u0433\u0430\u044e";
  this.act = "\u0418\u0449\u0443";
  this.adr = "\u041f\u043e\u0434\u0440\u043e\u0431\u043d\u0435\u0435";
  this.afG = "\u0426\u0435\u043d\u0430";
  this.afH = "\u043e\u0441\u0442\u0430\u0432\u044c\u0442\u0435 \u043f\u0443\u0441\u0442\u044b\u043c: \u043f\u043e \u0434\u043e\u0433\u043e\u0432\u043e\u0440\u0451\u043d\u043d\u043e\u0441\u0442\u0438";
  this.acT = "\u043f\u043e \u0434\u043e\u0433\u043e\u0432\u043e\u0440\u0451\u043d\u043d\u043e\u0441\u0442\u0438";
  this.adM = "\u0415\u0434\u0438\u043d\u0438\u0446\u0430\u043c\u0438, %";
  this.adN = "\u043a\u0430\u043a\u0443\u044e \u0434\u043e\u043b\u044e \u0446\u0435\u043d\u044b \u0432\u044b \u0431\u0435\u0440\u0451\u0442\u0435 \u0438\u043b\u0438 \u043f\u043b\u0430\u0442\u0438\u0442\u0435 \u0435\u0434\u0438\u043d\u0438\u0446\u0430\u043c\u0438: 100 \u2014 \u0432\u0441\u044e, 50 \u2014 \u043f\u043e\u043b\u043e\u0432\u0438\u043d\u0443";
  this.ag8 = "\u043e\u0442 0 \u0434\u043e 100";
  this.afF = "\u041e\u0431\u044a\u044f\u0432\u043b\u0435\u043d\u0438\u0435 \u043d\u0430 \u0434\u043e\u0441\u043a\u0435";
  this.aeQ = "\u041d\u0435 \u043f\u043e\u043b\u0443\u0447\u0438\u043b\u043e\u0441\u044c";
  this.acN = "\u041d\u0430 \u0434\u043e\u0441\u043a\u0435 \u043d\u0435\u0442 \u043c\u0435\u0441\u0442\u0430 \u0434\u043b\u044f \u0435\u0449\u0451 \u043e\u0434\u043d\u043e\u0433\u043e \u0432\u0430\u0448\u0435\u0433\u043e \u043e\u0431\u044a\u044f\u0432\u043b\u0435\u043d\u0438\u044f: \u0441\u043d\u0430\u0447\u0430\u043b\u0430 \u0441\u043d\u0438\u043c\u0438\u0442\u0435 \u043e\u0434\u043d\u043e.";
  this.agp = "\u0421\u043d\u044f\u0442\u044c \u0441 \u0434\u043e\u0441\u043a\u0438";
  this.ag9 = "\u041e\u0431\u0449\u0438\u0435 \u0441\u0447\u0435\u0442\u0430";
  this.agf = "\u0421\u0447\u0451\u0442 \u0441\u0435\u043c\u044c\u0438 \u0438\u043b\u0438 \u043a\u043e\u043c\u0430\u043d\u0434\u044b \u0434\u0435\u0440\u0436\u0430\u0442 \u0441\u0447\u0435\u0442\u0430 \u0435\u0451 \u0443\u0447\u0430\u0441\u0442\u043d\u0438\u043a\u043e\u0432, \u0430 \u043d\u0435 \u0443\u0441\u0442\u0440\u043e\u0439\u0441\u0442\u0432\u0430: \u043a\u0430\u0436\u0434\u044b\u0439 \u0434\u0435\u0440\u0436\u0430\u0442\u0435\u043b\u044c \u043f\u043e\u043b\u044c\u0437\u0443\u0435\u0442\u0441\u044f \u0438\u043c \u0441 \u043b\u044e\u0431\u043e\u0433\u043e \u0441\u0432\u043e\u0435\u0433\u043e \u0443\u0441\u0442\u0440\u043e\u0439\u0441\u0442\u0432\u0430, \u0430 \u043f\u043e\u0442\u0435\u0440\u044f\u043d\u043d\u044b\u0439 \u0442\u0435\u043b\u0435\u0444\u043e\u043d \u0437\u0430\u043c\u0435\u043d\u044f\u0435\u0442\u0441\u044f \u043e\u0434\u0438\u043d \u0440\u0430\u0437 \u2014 \u0432 \u0441\u043e\u0431\u0441\u0442\u0432\u0435\u043d\u043d\u043e\u043c \u0441\u0447\u0451\u0442\u0435 \u0447\u0435\u043b\u043e\u0432\u0435\u043a\u0430.";
  this.aez = "\u043e\u0431\u0449\u0438\u0445 \u0441\u0447\u0435\u0442\u043e\u0432 \u043f\u043e\u043a\u0430 \u043d\u0435\u0442";
