  this.agb = "\u041d\u0430\u0437\u0432\u0430\u043d\u0438\u0435";
  this.agc = "\u0421\u043d\u0430\u0447\u0430\u043b\u0430 \u043e\u0442\u043a\u0440\u043e\u0439\u0442\u0435 \u0441\u0432\u043e\u0439 \u0441\u0447\u0451\u0442: \u043e\u0431\u0449\u0438\u0439 \u0441\u0447\u0451\u0442 \u0434\u0435\u0440\u0436\u0430\u0442 \u0441\u0447\u0435\u0442\u0430 \u0435\u0433\u043e \u0443\u0447\u0430\u0441\u0442\u043d\u0438\u043a\u043e\u0432.";
  this.age = "\u0421\u0447\u0451\u0442 \u043e\u0442\u043a\u0440\u044b\u0442, \u0432\u044b \u0435\u0433\u043e \u0434\u0435\u0440\u0436\u0430\u0442\u0435\u043b\u044c. \u0421\u0432\u043e\u0435\u0439 \u043a\u0440\u0435\u0434\u0438\u0442\u043d\u043e\u0439 \u043b\u0438\u043d\u0438\u0438 \u0443 \u043d\u0435\u0433\u043e \u043d\u0435\u0442: \u043e\u043d \u0442\u0440\u0430\u0442\u0438\u0442 \u0442\u043e, \u0447\u0442\u043e \u0435\u043c\u0443 \u0437\u0430\u043f\u043b\u0430\u0442\u0438\u043b\u0438, \u0438\u043b\u0438 \u043b\u0438\u043d\u0438\u044e, \u043a\u043e\u0442\u043e\u0440\u0443\u044e \u0435\u043c\u0443 \u043e\u0434\u043e\u043b\u0436\u0438\u043b \u0443\u0447\u0430\u0441\u0442\u043d\u0438\u043a. \u041e\u0441\u0442\u0430\u043b\u044c\u043d\u044b\u0445 \u0434\u043e\u0431\u0430\u0432\u044c\u0442\u0435 \u0432 \u0440\u0430\u0437\u0434\u0435\u043b\u0435 \u00ab\u0414\u0435\u0440\u0436\u0430\u0442\u0435\u043b\u0438\u00bb.";
  this.adD = "\u0414\u0435\u0440\u0436\u0430\u0442\u0435\u043b\u0438";
  this.adE = "\u041a\u0442\u043e \u043c\u043e\u0436\u0435\u0442 \u0434\u0435\u0439\u0441\u0442\u0432\u043e\u0432\u0430\u0442\u044c \u043e\u0442 \u0438\u043c\u0435\u043d\u0438 \u044d\u0442\u043e\u0433\u043e \u0441\u0447\u0451\u0442\u0430: \u0441\u0447\u0435\u0442\u0430 \u0443\u0447\u0430\u0441\u0442\u043d\u0438\u043a\u043e\u0432, \u0443 \u043a\u0430\u0436\u0434\u043e\u0433\u043e \u2014 \u0447\u0442\u043e \u043e\u043d \u043c\u043e\u0436\u0435\u0442 \u0438 \u0441\u043a\u043e\u043b\u044c\u043a\u043e. \u0414\u0435\u0440\u0436\u0430\u0442\u0435\u043b\u044c \u043f\u043e\u043b\u044c\u0437\u0443\u0435\u0442\u0441\u044f \u0441\u0447\u0451\u0442\u043e\u043c \u0441 \u043b\u044e\u0431\u043e\u0433\u043e \u0441\u0432\u043e\u0435\u0433\u043e \u0443\u0441\u0442\u0440\u043e\u0439\u0441\u0442\u0432\u0430.";
  this.acp = "\u0414\u043e\u0431\u0430\u0432\u0438\u0442\u044c \u0434\u0435\u0440\u0436\u0430\u0442\u0435\u043b\u044f";
  this.adC = "\u0423\u0447\u0430\u0441\u0442\u043d\u0438\u043a";
  this.agV = "\u0432\u044b";
  this.agB = "\u0414\u0432\u0435 \u043f\u043e\u0434\u043f\u0438\u0441\u0438";
  this.agz = "\u0414\u0432\u0430 \u0434\u0435\u0440\u0436\u0430\u0442\u0435\u043b\u044f \u0434\u043b\u044f \u043f\u043b\u0430\u0442\u0435\u0436\u0430 \u0441\u0432\u044b\u0448\u0435";
  this.agA = "\u043e\u0441\u0442\u0430\u0432\u044c\u0442\u0435 \u043f\u0443\u0441\u0442\u044b\u043c: \u0434\u043b\u044f \u043b\u044e\u0431\u043e\u0433\u043e \u043f\u043b\u0430\u0442\u0435\u0436\u0430 \u0434\u043e\u0441\u0442\u0430\u0442\u043e\u0447\u043d\u043e \u043e\u0434\u043d\u043e\u0433\u043e \u0434\u0435\u0440\u0436\u0430\u0442\u0435\u043b\u044f";
  this.agD = "\u0423\u0441\u0442\u0430\u043d\u043e\u0432\u043b\u0435\u043d\u043e";
