  this.agx = "\u041f\u043b\u0430\u0442\u0435\u0436\u0438, \u043a\u043e\u0442\u043e\u0440\u044b\u0435 \u0436\u0434\u0443\u0442 \u0432\u0442\u043e\u0440\u043e\u0433\u043e \u0434\u0435\u0440\u0436\u0430\u0442\u0435\u043b\u044f";
  this.agw = "\u041f\u043b\u0430\u0442\u0451\u0436 \u0441\u0432\u044b\u0448\u0435 \u043f\u043e\u0440\u043e\u0433\u0430 \u0441\u0447\u0451\u0442\u0430 \u043f\u0440\u0435\u0434\u043b\u0430\u0433\u0430\u0435\u0442 \u043e\u0434\u0438\u043d \u0434\u0435\u0440\u0436\u0430\u0442\u0435\u043b\u044c, \u0430 \u043f\u043e\u0434\u0442\u0432\u0435\u0440\u0436\u0434\u0430\u0435\u0442 \u0434\u0440\u0443\u0433\u043e\u0439. \u041d\u0435\u043f\u043e\u0434\u0442\u0432\u0435\u0440\u0436\u0434\u0451\u043d\u043d\u044b\u0439 \u0437\u0430 \u043d\u0435\u0434\u0435\u043b\u044e \u043f\u043b\u0430\u0442\u0451\u0436 \u043e\u0442\u043f\u0430\u0434\u0430\u0435\u0442.";
  this.af2 = "\u043d\u0438\u0447\u0435\u0433\u043e \u043d\u0435 \u0436\u0434\u0451\u0442";
  this.adf = "\u041f\u043e\u0434\u0442\u0432\u0435\u0440\u0434\u0438\u0442\u044c \u0438 \u0437\u0430\u043f\u043b\u0430\u0442\u0438\u0442\u044c";
  this.afJ = "\u041f\u0440\u0435\u0434\u043b\u043e\u0436\u0438\u043b";
  this.afI = "\u041f\u043b\u0430\u0442\u0451\u0436 \u0436\u0434\u0451\u0442 \u0432\u0442\u043e\u0440\u043e\u0433\u043e \u0434\u0435\u0440\u0436\u0430\u0442\u0435\u043b\u044f";
  this.aeh = "\u042d\u0442\u043e\u0442 \u043f\u043b\u0430\u0442\u0451\u0436 \u043f\u0440\u0435\u0434\u043b\u043e\u0436\u0438\u043b\u0438 \u0432\u044b: \u043f\u043e\u0434\u0442\u0432\u0435\u0440\u0434\u0438\u0442\u044c \u0435\u0433\u043e \u0434\u043e\u043b\u0436\u0435\u043d \u0434\u0440\u0443\u0433\u043e\u0439 \u0434\u0435\u0440\u0436\u0430\u0442\u0435\u043b\u044c.";
  this.aei = "\u042d\u0442\u043e\u043c\u0443 \u043f\u043b\u0430\u0442\u0435\u0436\u0443 \u043d\u0443\u0436\u0435\u043d \u0432\u0442\u043e\u0440\u043e\u0439 \u0434\u0435\u0440\u0436\u0430\u0442\u0435\u043b\u044c.";
  this.afy = "\u041f\u043e\u043b\u0438\u0442\u0438\u043a\u0430";
  this.afE = "\u0421\u043e\u0431\u0441\u0442\u0432\u0435\u043d\u043d\u0430\u044f \u043f\u043e\u043b\u0438\u0442\u0438\u043a\u0430 \u043e\u0431\u0449\u0438\u043d\u044b: \u0434\u0435\u0439\u0441\u0442\u0432\u0443\u0435\u0442 \u0441 \u043c\u043e\u043c\u0435\u043d\u0442\u0430 \u0441\u043e\u0445\u0440\u0430\u043d\u0435\u043d\u0438\u044f \u0434\u043b\u044f \u043a\u0430\u0436\u0434\u043e\u0433\u043e \u0441\u0447\u0451\u0442\u0430. \u041b\u0438\u043d\u0438\u0438, \u0432\u044b\u0434\u0430\u043d\u043d\u044b\u0435 \u0440\u0430\u043d\u044c\u0448\u0435, \u043e\u0441\u0442\u0430\u044e\u0442\u0441\u044f \u043a\u0430\u043a \u0435\u0441\u0442\u044c. \u0425\u0430\u0431, \u043d\u0430 \u043a\u043e\u0442\u043e\u0440\u043e\u043c \u0441\u0442\u043e\u0438\u0442 \u043e\u0431\u0449\u0438\u043d\u0430, \u043c\u043e\u0436\u0435\u0442 \u0440\u0430\u0437\u0440\u0435\u0448\u0430\u0442\u044c \u043c\u0435\u043d\u044c\u0448\u0435, \u0447\u0435\u043c \u043f\u0440\u0435\u0434\u043b\u0430\u0433\u0430\u044e\u0442 \u0432 \u0434\u0440\u0443\u0433\u0438\u0445 \u043c\u0435\u0441\u0442\u0430\u0445.";
