  this.ajA = "\u041d\u0435 \u0432\u0434\u0430\u043b\u043e\u0441\u044f";
  this.ahx = "\u041d\u0430 \u0434\u043e\u0448\u0446\u0456 \u043d\u0435\u043c\u0430\u0454 \u043c\u0456\u0441\u0446\u044f \u0434\u043b\u044f \u0449\u0435 \u043e\u0434\u043d\u043e\u0433\u043e \u0432\u0430\u0448\u043e\u0433\u043e \u043e\u0433\u043e\u043b\u043e\u0448\u0435\u043d\u043d\u044f: \u0441\u043f\u0435\u0440\u0448\u0443 \u0437\u043d\u0456\u043c\u0456\u0442\u044c \u043e\u0434\u043d\u0435.";
