  this.aj7 = "\u041d\u043e\u0432\u0438\u0439 \u0441\u043f\u0456\u043b\u044c\u043d\u0438\u0439 \u0440\u0430\u0445\u0443\u043d\u043e\u043a";
  this.akV = "\u041d\u0430\u0437\u0432\u0430";
  this.akW = "\u0421\u043f\u0435\u0440\u0448\u0443 \u0432\u0456\u0434\u043a\u0440\u0438\u0439\u0442\u0435 \u0441\u0432\u0456\u0439 \u0440\u0430\u0445\u0443\u043d\u043e\u043a: \u0441\u043f\u0456\u043b\u044c\u043d\u0438\u0439 \u0440\u0430\u0445\u0443\u043d\u043e\u043a \u0442\u0440\u0438\u043c\u0430\u044e\u0442\u044c \u0440\u0430\u0445\u0443\u043d\u043a\u0438 \u0439\u043e\u0433\u043e \u0443\u0447\u0430\u0441\u043d\u0438\u043a\u0456\u0432.";
  this.akY = "\u0420\u0430\u0445\u0443\u043d\u043e\u043a \u0432\u0456\u0434\u043a\u0440\u0438\u0442\u043e, \u0432\u0438 \u0439\u043e\u0433\u043e \u0442\u0440\u0438\u043c\u0430\u0447. \u0412\u043b\u0430\u0441\u043d\u043e\u0457 \u043a\u0440\u0435\u0434\u0438\u0442\u043d\u043e\u0457 \u043b\u0456\u043d\u0456\u0457 \u0432\u0456\u043d \u043d\u0435 \u043c\u0430\u0454: \u0432\u0438\u0442\u0440\u0430\u0447\u0430\u0454 \u0442\u0435, \u0449\u043e \u0439\u043e\u043c\u0443 \u0437\u0430\u043f\u043b\u0430\u0442\u0438\u043b\u0438, \u0430\u0431\u043e \u043b\u0456\u043d\u0456\u044e, \u044f\u043a\u0443 \u0439\u043e\u043c\u0443 \u043f\u043e\u0437\u0438\u0447\u0438\u0432 \u0443\u0447\u0430\u0441\u043d\u0438\u043a. \u0406\u043d\u0448\u0438\u0445 \u0434\u043e\u0434\u0430\u0439\u0442\u0435 \u0432 \u0440\u043e\u0437\u0434\u0456\u043b\u0456 \u00ab\u0422\u0440\u0438\u043c\u0430\u0447\u0456\u00bb.";
  this.ain = "\u0422\u0440\u0438\u043c\u0430\u0447\u0456";
  this.aio = "\u0425\u0442\u043e \u043c\u043e\u0436\u0435 \u0434\u0456\u044f\u0442\u0438 \u0432\u0456\u0434 \u0456\u043c\u0435\u043d\u0456 \u0446\u044c\u043e\u0433\u043e \u0440\u0430\u0445\u0443\u043d\u043a\u0443: \u0440\u0430\u0445\u0443\u043d\u043a\u0438 \u0443\u0447\u0430\u0441\u043d\u0438\u043a\u0456\u0432, \u0443 \u043a\u043e\u0436\u043d\u043e\u0433\u043e \u2014 \u0449\u043e \u0432\u0456\u043d \u043c\u043e\u0436\u0435 \u0456 \u0441\u043a\u0456\u043b\u044c\u043a\u0438. \u0422\u0440\u0438\u043c\u0430\u0447 \u043a\u043e\u0440\u0438\u0441\u0442\u0443\u0454\u0442\u044c\u0441\u044f \u0440\u0430\u0445\u0443\u043d\u043a\u043e\u043c \u0456\u0437 \u0431\u0443\u0434\u044c-\u044f\u043a\u043e\u0433\u043e \u0441\u0432\u043e\u0433\u043e \u043f\u0440\u0438\u0441\u0442\u0440\u043e\u044e.";
  this.ah9 = "\u0414\u043e\u0434\u0430\u0442\u0438 \u0442\u0440\u0438\u043c\u0430\u0447\u0430";
  this.aim = "\u0423\u0447\u0430\u0441\u043d\u0438\u043a";
  this.alF = "\u0432\u0438";
  this.all = "\u0414\u0432\u0430 \u043f\u0456\u0434\u043f\u0438\u0441\u0438";
  this.alj = "\u0414\u0432\u0430 \u0442\u0440\u0438\u043c\u0430\u0447\u0456 \u0434\u043b\u044f \u043f\u043b\u0430\u0442\u0435\u0436\u0443 \u043f\u043e\u043d\u0430\u0434";
  this.alk = "\u0437\u0430\u043b\u0438\u0448\u0442\u0435 \u043f\u043e\u0440\u043e\u0436\u043d\u0456\u043c: \u0434\u043b\u044f \u0431\u0443\u0434\u044c-\u044f\u043a\u043e\u0433\u043e \u043f\u043b\u0430\u0442\u0435\u0436\u0443 \u0434\u043e\u0441\u0438\u0442\u044c \u043e\u0434\u043d\u043e\u0433\u043e \u0442\u0440\u0438\u043c\u0430\u0447\u0430";
  this.aln = "\u0412\u0441\u0442\u0430\u043d\u043e\u0432\u043b\u0435\u043d\u043e";
  this.alm = "\u0422\u0435\u043f\u0435\u0440 \u0434\u043b\u044f \u0431\u0443\u0434\u044c-\u044f\u043a\u043e\u0433\u043e \u043f\u043b\u0430\u0442\u0435\u0436\u0443 \u0434\u043e\u0441\u0438\u0442\u044c \u043e\u0434\u043d\u043e\u0433\u043e \u0442\u0440\u0438\u043c\u0430\u0447\u0430.";
  this.alh = "\u041f\u043b\u0430\u0442\u0435\u0436\u0456, \u0449\u043e \u0447\u0435\u043a\u0430\u044e\u0442\u044c \u043d\u0430 \u0434\u0440\u0443\u0433\u043e\u0433\u043e \u0442\u0440\u0438\u043c\u0430\u0447\u0430";
  this.alg = "\u041f\u043b\u0430\u0442\u0456\u0436 \u043f\u043e\u043d\u0430\u0434 \u043f\u043e\u0440\u0456\u0433 \u0440\u0430\u0445\u0443\u043d\u043a\u0443 \u043f\u0440\u043e\u043f\u043e\u043d\u0443\u0454 \u043e\u0434\u0438\u043d \u0442\u0440\u0438\u043c\u0430\u0447, \u0430 \u043f\u0456\u0434\u0442\u0432\u0435\u0440\u0434\u0436\u0443\u0454 \u0456\u043d\u0448\u0438\u0439. \u041d\u0435 \u043f\u0456\u0434\u0442\u0432\u0435\u0440\u0434\u0436\u0435\u043d\u0438\u0439 \u0437\u0430 \u0442\u0438\u0436\u0434\u0435\u043d\u044c \u043f\u043b\u0430\u0442\u0456\u0436 \u0432\u0456\u0434\u043f\u0430\u0434\u0430\u0454.";
  this.ajM = "\u043d\u0456\u0447\u043e\u0433\u043e \u043d\u0435 \u0447\u0435\u043a\u0430\u0454";
  this.ahZ = "\u041f\u0456\u0434\u0442\u0432\u0435\u0440\u0434\u0438\u0442\u0438 \u0439 \u0437\u0430\u043f\u043b\u0430\u0442\u0438\u0442\u0438";
  this.akt = "\u0417\u0430\u043f\u0440\u043e\u043f\u043e\u043d\u0443\u0432\u0430\u0432";
  this.aks = "\u041f\u043b\u0430\u0442\u0456\u0436 \u0447\u0435\u043a\u0430\u0454 \u043d\u0430 \u0434\u0440\u0443\u0433\u043e\u0433\u043e \u0442\u0440\u0438\u043c\u0430\u0447\u0430";
  this.aj1 = "\u0426\u0435\u0439 \u043f\u043b\u0430\u0442\u0456\u0436 \u0437\u0430\u043f\u0440\u043e\u043f\u043e\u043d\u0443\u0432\u0430\u043b\u0438 \u0432\u0438: \u043f\u0456\u0434\u0442\u0432\u0435\u0440\u0434\u0438\u0442\u0438 \u0439\u043e\u0433\u043e \u043c\u0430\u0454 \u0456\u043d\u0448\u0438\u0439 \u0442\u0440\u0438\u043c\u0430\u0447.";
  this.aj2 = "\u0426\u044c\u043e\u043c\u0443 \u043f\u043b\u0430\u0442\u0435\u0436\u0443 \u043f\u043e\u0442\u0440\u0456\u0431\u0435\u043d \u0434\u0440\u0443\u0433\u0438\u0439 \u0442\u0440\u0438\u043c\u0430\u0447.";
  this.aki = "\u041f\u043e\u043b\u0456\u0442\u0438\u043a\u0430";
  this.ako = "\u0412\u043b\u0430\u0441\u043d\u0430 \u043f\u043e\u043b\u0456\u0442\u0438\u043a\u0430 \u0433\u0440\u043e\u043c\u0430\u0434\u0438: \u0434\u0456\u0454 \u0437 \u043c\u043e\u043c\u0435\u043d\u0442\u0443 \u0437\u0431\u0435\u0440\u0435\u0436\u0435\u043d\u043d\u044f \u0434\u043b\u044f \u043a\u043e\u0436\u043d\u043e\u0433\u043e \u0440\u0430\u0445\u0443\u043d\u043a\u0443. \u041b\u0456\u043d\u0456\u0457, \u0432\u0438\u0434\u0430\u043d\u0456 \u0440\u0430\u043d\u0456\u0448\u0435, \u043b\u0438\u0448\u0430\u044e\u0442\u044c\u0441\u044f \u044f\u043a \u0454. \u0425\u0430\u0431, \u043d\u0430 \u044f\u043a\u043e\u043c\u0443 \u0441\u0442\u043e\u0457\u0442\u044c \u0433\u0440\u043e\u043c\u0430\u0434\u0430, \u043c\u043e\u0436\u0435 \u0434\u043e\u0437\u0432\u043e\u043b\u044f\u0442\u0438 \u043c\u0435\u043d\u0448\u0435, \u043d\u0456\u0436 \u043f\u0440\u043e\u043f\u043e\u043d\u0443\u044e\u0442\u044c \u0434\u0435\u0456\u043d\u0434\u0435.";
  this.akk = "\u0412\u0441\u0442\u0443\u043f \u0456 \u0431\u0456\u0437\u043d\u0435\u0441\u0438";
  this.akl = "\u041f\u0440\u0438\u0432\u0430\u0442\u043d\u0456 \u043e\u0441\u043e\u0431\u0438";
  this.akm = "\u041a\u0440\u0435\u0434\u0438\u0442 \u043f\u0440\u0438\u0432\u0430\u0442\u043d\u0456\u0439 \u043e\u0441\u043e\u0431\u0456, \u043d\u0430\u0432\u0456\u0442\u044c \u0431\u0435\u0437\u0432\u0456\u0434\u0441\u043e\u0442\u043a\u043e\u0432\u0438\u0439, \u043c\u043e\u0436\u0435 \u043f\u0456\u0434\u043f\u0430\u0434\u0430\u0442\u0438 \u043f\u0456\u0434 \u043f\u0440\u0430\u0432\u0438\u043b\u0430 \u0441\u043f\u043e\u0436\u0438\u0432\u0447\u043e\u0433\u043e \u043a\u0440\u0435\u0434\u0438\u0442\u0443. \u0414\u0435 \u043b\u044e\u0434\u0438 \u0441\u043f\u0435\u0440\u0448\u0443 \u0437\u0430\u0440\u043e\u0431\u043b\u044f\u044e\u0442\u044c, \u0430 \u043f\u043e\u0442\u0456\u043c \u0432\u0438\u0442\u0440\u0430\u0447\u0430\u044e\u0442\u044c, \u043a\u0440\u0435\u0434\u0438\u0442 \u043d\u0435 \u0432\u0438\u0434\u0430\u0454\u0442\u044c\u0441\u044f \u0456 \u043f\u0438\u0442\u0430\u043d\u043d\u044f \u043d\u0435 \u0432\u0438\u043d\u0438\u043a\u0430\u0454.";
